    },
    {
      "card_ids": ["C35"],
      "claim": "Cebranopadol, a fluorinated fused heterocycle with a basic amine, had mean oral bioavailability of about 40% in the fasted state, still clearly above 20% and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Thalidomide, a small heterocyclic lactam, had probably high absolute oral bioavailability of 80–100% in fasting healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability values from about 40% to 100%, consistently above the 20% threshold, so the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "Some analogues have only moderate bioavailability (40–67%), but all remain above the 20% threshold."
  ],
